import { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import axios from "axios";

import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import UserDashboard from "./components/UserDashboard";

const API_URL = "http://localhost:5000";

function App() {
  // ===================== STATE =====================
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    yearLevel: "",
    block: "",
    image: null,
  });

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 2000);
    return () => clearInterval(interval);
  }, []);

  // ================= AUTH =================
  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      formData.append("yearLevel", candidateForm.yearLevel || "");
      formData.append("block", candidateForm.block || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        yearLevel: "",
        block: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  const theme = {
    background: darkMode ? "#1f1f2e" : "#f4f4f9",
    card: darkMode ? "#2c2c3a" : "#ffffff",
    text: darkMode ? "#f4f4f9" : "#1f1f2e",
    button: darkMode ? "#4f46e5" : "#6366f1",
  };

  // ===================== RETURN =====================
  return (
    <Router>
      <div
        style={{
          minHeight: "100vh",
          backgroundColor: theme.background,
          color: theme.text,
          padding: 20,
        }}
      >
        {/* HEADER */}
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <h1>SorSU Online Voting</h1>
          <div>
            <button
              onClick={() => setDarkMode(!darkMode)}
              style={headerButtonStyle(theme)}
            >
              {darkMode ? "Light Mode" : "Dark Mode"}
            </button>

            {/* Anonymous chart toggle only for admin */}
            {auth.role === "admin" && (
              <button
                onClick={() => setShowAnonymous(!showAnonymous)}
                style={headerButtonStyle(theme)}
              >
                {showAnonymous ? "Hide Anonymous Chart" : "Anonymous Chart"}
              </button>
            )}

            {auth.role === "admin" && (
              <button
                onClick={() => setElectionClosed(!electionClosed)}
                style={{
                  ...headerButtonStyle(theme),
                  backgroundColor: electionClosed ? "#10b981" : "#ef4444",
                }}
              >
                {electionClosed ? "Open Election" : "Close Election"}
              </button>
            )}

            <button
              onClick={handleLogout}
              style={{ ...headerButtonStyle(theme), backgroundColor: "#ef4444" }}
            >
              Logout
            </button>
          </div>
        </div>

        {message && <p style={{ marginTop: 10 }}>{message}</p>}

        {/* ROUTES */}
        <Routes>
          {/* ADMIN VIEW */}
          {auth.role === "admin" && (
            <Route
              path="/"
              element={
                <>
                  {showAnonymous ? (
                    <AdminAnonymousResults theme={theme} />
                  ) : (
                    <>
                      <h2 style={{ marginTop: 20 }}>Live Vote Monitor</h2>
                      <div
                        style={{
                          backgroundColor: theme.card,
                          padding: 15,
                          borderRadius: 8,
                          marginBottom: 20,
                        }}
                      >
                        <strong>Total Votes:</strong> {totalVotes}
                      </div>

                      <AdminPanel
                        candidateForm={candidateForm}
                        setCandidateForm={setCandidateForm}
                        onSave={handleSaveCandidate}
                        editId={editId}
                        setEditId={setEditId}
                        onDelete={handleDeleteCandidate}
                        candidates={candidates}
                        theme={theme}
                      />
                    </>
                  )}
                </>
              }
            />
          )}

          {/* USER VIEW */}
          {auth.role === "user" && (
            <>
              <Route path="/dashboard" element={<UserDashboard auth={auth} />} />
            </>
          )}
        </Routes>
      </div>
    </Router>
  );
}

// ===================== STYLES =====================
const headerButtonStyle = (theme) => ({
  marginRight: 10,
  padding: "8px 16px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: 5,
  cursor: "pointer",
});

export default App;
